// 严格命令形状和原报价绑定；三种业务均不接受外部资产权源或另一人的受领许可。
#include "family_inheritance_commands.hpp"
#include "resident/domains/actor_foundation/actor_foundation_json_visitor.hpp"
#include <set>
namespace hanmo::resident { namespace {
// 精确原批次选择保持顺序；同物品另批次不能替换用户实际确认的来源。
bool selection_equal(const InheritancePersonalSelection& a,const InheritancePersonalSelection& b){if(a.money!=b.money||a.lots.size()!=b.lots.size())return false;for(std::size_t i=0;i<a.lots.size();++i)if(a.lots[i].lot_id!=b.lots[i].lot_id||a.lots[i].item_id!=b.lots[i].item_id||a.lots[i].quantity!=b.lots[i].quantity)return false;return true;}
// ID长度与空值在边界即拒，不把任意长字符串带进权源查找。
StableId id(const BoundaryValue& v,const StableId& key,const StableId& path){auto result=boundary::get_string(v,key,path);if(result.empty()||result.size()>256)boundary::fail("InvalidInheritanceReference",path+"."+key);return result;}
}
static Outcome<FamilyInheritanceCommand> decode_selected_command(const StableId& kind,const BoundaryValue& value,Integer version){try{using namespace boundary;auto unique=validate_succession_json_unique(value);if(!unique.ok)return {false,{},unique.error};FamilyInheritanceCommand out;out.kind=kind;
 if(kind=="family_bequest_disclose"){fields(value,{"declaration_id"},{},kind);out.declaration_id=id(value,"declaration_id",kind);}
 else if(kind=="family_inheritance_accept"){if(version==2){fields(value,{"disclosure_fact_id","known_death"},{},kind);out.known_death=ActorKnownDeathReceiptRef{};ActorFoundationJsonVisitor c(field(value,"known_death",kind));auto valid=known_death_receipt_codec::fields(c,*out.known_death);if(valid.ok)valid=c.finish();if(!valid.ok)return {false,{},valid.error};if(out.known_death->report_id.empty()||out.known_death->report_id.size()>256||out.known_death->death.domain!="family_life"||out.known_death->death.kind!="family_death"||out.known_death->death.id.empty()||out.known_death->death.id.size()>256)fail("InvalidKnownDeathReceiptRef",kind);}else{fields(value,{"disclosure_fact_id","notice_binding_fact_id"},{},kind);out.notice_binding_fact_id=id(value,"notice_binding_fact_id",kind);}out.disclosure_fact_id=id(value,"disclosure_fact_id",kind);}
 else if(kind=="family_inheritance_settle"){fields(value,{"acceptance_fact_id","personal"},{},kind);out.acceptance_fact_id=id(value,"acceptance_fact_id",kind);const auto& personal=field(value,"personal",kind);fields(personal,{"money","lots"},{},kind+".personal");out.selected.money=integer(field(personal,"money",kind),kind);if(out.selected.money<0)fail("InvalidInheritanceMoney",kind);const auto& rows=array(field(personal,"lots",kind),kind);if(rows.size()>4096)fail("TooManyInheritanceLots",kind);std::set<StableId> ids;for(const auto& row:rows){fields(row,{"lot_id","item_id","quantity"},{},kind);SuccessionPersonalLot lot;lot.lot_id=id(row,"lot_id",kind);lot.item_id=id(row,"item_id",kind);lot.quantity=integer(field(row,"quantity",kind),kind);if(lot.quantity<=0||!ids.insert(lot.lot_id).second)fail("InvalidInheritanceLotSelection",kind);out.selected.lots.push_back(std::move(lot));}if(!out.selected.money&&out.selected.lots.empty())fail("EmptyInheritanceSelection",kind);}
 else fail("UnknownFamilyInheritanceCommand",kind);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
// 本人先过完整本域历史，再取实际会面、实收通知或已经接受的剩余产权报价。
Outcome<FamilyInheritanceQuote> preview_family_inheritance_command(const CommonStore& c,const FamilyBequestState& grants,const FamilyDeathState& deaths,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& meetings,const FamilyInheritancePolicy& policy,const FamilyInheritanceState& state,const FamilyInheritanceAccess& access,const StableId& actor,const FamilyInheritanceCommand& command){
 if(!policy.enabled)return {false,{},common_failure("FamilyInheritanceProfileRequired").error};if(actor!=c.state().metadata.player_actor_id)return {false,{},common_failure("PlayerCommandAuthorityRequired").error};const auto* person=c.actor(actor);if(!person||!person->alive||!person->available)return {false,{},common_failure("InheritanceLivingActorRequired").error};auto checked=validate_family_inheritance(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,access.clearance,access.sources);if(!checked.ok)return {false,{},checked.error};FamilyInheritanceQuote quote;
 if(command.kind=="family_bequest_disclose"){if(command.known_death||!command.disclosure_fact_id.empty()||!command.notice_binding_fact_id.empty()||!command.acceptance_fact_id.empty()||command.selected.money||!command.selected.lots.empty())return {false,{},common_failure("InvalidInheritanceCommand").error};for(const auto& row:state.disclosures.rows())if(row.second.source.declaration_id==command.declaration_id)return {false,{},common_failure("BequestAlreadyDisclosed",row.first).error};auto source=preview_bequest_disclosure(c,grants,interaction,catalog,meetings,command.declaration_id,policy.selected_version,access.sources?&access.sources->people():nullptr);if(!source.ok)return {false,{},source.error};quote.disclosure=std::move(source.value);}
 else if(command.kind=="family_inheritance_accept"){if(!command.declaration_id.empty()||!command.acceptance_fact_id.empty()||command.selected.money||!command.selected.lots.empty())return {false,{},common_failure("InvalidInheritanceCommand").error};if(policy.selected_version==2&&(!access.sources||!command.known_death||!command.notice_binding_fact_id.empty()))return {false,{},common_failure("InheritanceCompleteSourcesRequired",{},ErrorKind::unsupported_capability).error};if(policy.selected_version==1&&command.known_death)return {false,{},common_failure("InheritanceProfileMismatch").error};auto source=policy.selected_version==2?preview_family_inheritance_acceptance_v2(c,grants,deaths,catalog,access.player,policy,state,command.disclosure_fact_id,*command.known_death,*access.sources,access.clearance):preview_family_inheritance_acceptance(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,command.disclosure_fact_id,command.notice_binding_fact_id,access.clearance,access.sources);if(!source.ok)return {false,{},source.error};quote.acceptance=std::move(source.value);}
 else if(command.kind=="family_inheritance_settle"){if(command.known_death||!command.declaration_id.empty()||!command.disclosure_fact_id.empty()||!command.notice_binding_fact_id.empty())return {false,{},common_failure("InvalidInheritanceCommand").error};auto source=preview_family_inheritance_settlement(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,command.acceptance_fact_id,command.selected,access.clearance,access.sources);if(!source.ok)return {false,{},source.error};quote.settlement=std::move(source.value);}
 else return {false,{},common_failure("UnknownFamilyInheritanceCommand").error};return {true,std::move(quote),{}};
}
// 原资产函数持Common保存点，本层只验证命令报价不可错配并形成精确事实回执。
Outcome<FamilyEffect> apply_family_inheritance_command(CommonStore& c,const FamilyBequestState& grants,const FamilyDeathState& deaths,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& meetings,const FamilyInheritancePolicy& policy,FamilyInheritanceState& state,const FamilyInheritanceAccess& access,const StableId& actor,const FamilyInheritanceCommand& command,const FamilyInheritanceQuote& quote){
 auto fresh=preview_family_inheritance_command(c,grants,deaths,interaction,catalog,meetings,policy,state,access,actor,command);if(!fresh.ok)return {false,{},fresh.error};Outcome<StableId> result;StableId beneficiary;
 if(command.kind=="family_bequest_disclose"){if(!quote.disclosure||quote.acceptance||quote.settlement||quote.disclosure->source.declaration_id!=command.declaration_id||!bequest_disclosure_source_equal(quote.disclosure->source,fresh.value.disclosure->source))return {false,{},common_failure("StaleInheritanceDisclosure").error};beneficiary=quote.disclosure->source.beneficiary_actor_id;result=disclose_family_bequest(c,grants,deaths,interaction,catalog,meetings,access.player,access.received_notice,policy,state,*quote.disclosure,access.clearance,access.sources);}
 else if(command.kind=="family_inheritance_accept"){if(!quote.acceptance||quote.disclosure||quote.settlement||quote.acceptance->decision.disclosure_fact_id!=command.disclosure_fact_id||quote.acceptance->decision.notice_binding_fact_id!=command.notice_binding_fact_id)return {false,{},common_failure("StaleInheritanceAcceptance").error};if(policy.selected_version==2){if(!quote.acceptance->decision.known_death||!command.known_death)return {false,{},common_failure("StaleInheritanceAcceptance").error};const auto& saved=quote.acceptance->decision.known_death->receipt;const auto& selected=*command.known_death;if(saved.report_id!=selected.report_id||saved.death.domain!=selected.death.domain||saved.death.kind!=selected.death.kind||saved.death.id!=selected.death.id)return {false,{},common_failure("StaleInheritanceAcceptance").error};}beneficiary=actor;result=accept_family_inheritance(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,*quote.acceptance,access.clearance,access.sources);}
 else {if(!quote.settlement||quote.disclosure||quote.acceptance||quote.settlement->entitlement.acceptance_fact_id!=command.acceptance_fact_id||!selection_equal(quote.settlement->selected,command.selected))return {false,{},common_failure("StaleInheritanceSettlement").error};beneficiary=actor;result=settle_family_inheritance(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,*quote.settlement,access.clearance,access.sources);}
 if(!result.ok)return {false,{},result.error};FamilyEffect effect;effect.success=true;effect.fact_id=result.value;effect.actor_id=actor;effect.heir_actor_id=beneficiary;effect.player_actor_id=actor;return {true,std::move(effect),{}};
}
// 缓存回执只能引用原业务事实及当时本人，不能将公开回执冒作交割或控制继承。
Status validate_family_inheritance_receipt(const FamilyBequestState& grants,const FamilyInheritanceState& state,const StableId& kind,const StableId& actor,Integer tick,const FamilyEffect& effect){
 if(effect.success!=std::optional<bool>{true}||effect.already_completed||effect.code||effect.actor_id!=std::optional<StableId>{actor}||effect.player_actor_id!=std::optional<StableId>{actor}||!effect.fact_id||!effect.heir_actor_id)return common_failure("InvalidInheritanceReceipt");
 if(kind=="family_bequest_disclose"){const auto* d=state.disclosures.find(*effect.fact_id);if(d&&d->kind=="family_bequest_disclosed"&&d->source.tick==tick&&d->source.donor_actor_id==actor&&d->source.beneficiary_actor_id==*effect.heir_actor_id)return common_success();}
 else if(kind=="family_inheritance_accept"){const auto* a=state.acceptances.find(*effect.fact_id);if(a&&a->kind=="family_bequest_accepted"&&a->tick==tick&&a->beneficiary_actor_id==actor&&*effect.heir_actor_id==actor&&grants.declarations.find(a->declaration_id))return common_success();}
 else if(kind=="family_inheritance_settle"){const auto* s=state.settlements.find(*effect.fact_id);const auto* a=s?state.acceptances.find(s->acceptance_fact_id):nullptr;if(s&&a&&s->kind=="family_inheritance_settled"&&s->tick==tick&&a->beneficiary_actor_id==actor&&s->transfer.successor_actor_id==actor&&*effect.heir_actor_id==actor)return common_success();}
 return common_failure("InheritanceReceiptSourceMismatch");
}
Outcome<FamilyInheritanceCommand> decode_family_inheritance_command(const StableId& kind,const BoundaryValue& v){return decode_selected_command(kind,v,1);}
Outcome<FamilyInheritanceCommand> decode_family_inheritance_command_v2(const StableId& kind,const BoundaryValue& v){return decode_selected_command(kind,v,2);}
}
